From 0a00a9a05b357dafae86bf8af879aa601f101eba Mon Sep 17 00:00:00 2001
From: Yuanhan Liu <yuanhan.liu@linux.intel.com>
Date: Sun, 4 Sep 2011 06:02:14 +0800
Subject: [PATCH] intel: fix build error

Fix a build error introduced by commit 6862b54f:
i965_dri.so.tmp: undefined reference to `strerr'

Signed-off-by: Yuanhan Liu <yuanhan.liu@linux.intel.com>
Reviewed-by: Paul Berry <stereotype441@gmail.com>

diff --git a/src/mesa/drivers/dri/intel/intel_batchbuffer.c b/src/mesa/drivers/dri/intel/intel_batchbuffer.c
index c4bb836f6e..98ae4e9d5f 100644
--- a/src/mesa/drivers/dri/intel/intel_batchbuffer.c
+++ b/src/mesa/drivers/dri/intel/intel_batchbuffer.c
@@ -138,7 +138,7 @@ do_flush_locked(struct intel_context *intel)
    }

    if (ret != 0) {
-      fprintf(stderr, "intel_do_flush_locked failed: %s\n", strerr(ret));
+      fprintf(stderr, "intel_do_flush_locked failed: %s\n", strerror(ret));
       exit(1);
    }
    intel->vtbl.new_batch(intel);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the use of an incorrect function name `strerr` instead of the correct `strerror`, leading to an undefined reference error during the build process. This indicates that the code was attempting to call a non-existent function, which is a common issue when function names are misspelled or incorrectly referenced.

        Commit message:
        intel: fix build error

Fix a build error introduced by commit 6862b54f:
i965_dri.so.tmp: undefined reference to `strerr'

Signed-off-by: Yuanhan Liu <yuanhan.liu@linux.intel.com>
Reviewed-by: Paul Berry <stereotype441@gmail.com>  

        Patch:
          */
 static void
 do_flush_locked(struct intel_context *intel)
 {
    struct intel_batchbuffer *batch = &intel->batch;
    int ret = 0;

    ret = drm_intel_bo_subdata(batch->bo, 0, 4*batch->used, batch->map);
    if (ret == 0 && batch->state_batch_offset != batch->bo->size) {
       ret = drm_intel_bo_subdata(batch->bo,
 				 batch->state_batch_offset,
 				 batch->bo->size - batch->state_batch_offset,
 				 (char *)batch->map + batch->state_batch_offset);
    }

    if (!intel->intelScreen->no_hw) {
       int ring;

       if (intel->gen < 6 || !batch->is_blit) {
 	 ring = I915_EXEC_RENDER;
       } else {
 	 ring = I915_EXEC_BLT;
       }

       if (ret == 0)
 	 ret = drm_intel_bo_mrb_exec(batch->bo, 4*batch->used, NULL, 0, 0, ring);
    }

    if (unlikely(INTEL_DEBUG & DEBUG_BATCH)) {
       drm_intel_bo_map(batch->bo, false);
       intel_decode(batch->bo->virtual, batch->used,
 		   batch->bo->offset,
 		   intel->intelScreen->deviceID, GL_TRUE);
       drm_intel_bo_unmap(batch->bo);

       if (intel->vtbl.debug_batch != NULL)
 	 intel->vtbl.debug_batch(intel);
    }

    if (ret != 0) {
-      fprintf(stderr, "intel_do_flush_locked failed: %s\n", strerr(ret));
+      fprintf(stderr, "intel_do_flush_locked failed: %s\n", strerror(ret));
       exit(1);
    }
    intel->vtbl.new_batch(intel);
 }



